const std::size_t n = polygon.size();
if (n == 0) return CGAL::ON_UNBOUNDED_SIDE;

// First check if the point lies on any edge
for (std::size_t i = 0; i < n; ++i) {
    const Point_2& p1 = polygon[i];
    const Point_2& p2 = polygon[(i + 1) % n];

    // Check if point is collinear with the edge
    const CGAL::Sign orient = CGAL::orientation(p1, p2, point);
    if (orient == CGAL::ZERO) {
        // Check if point lies within the edge segment
        const bool between_x = (point.x() >= std::min(p1.x(), p2.x())) && 
                               (point.x() <= std::max(p1.x(), p2.x()));
        const bool between_y = (point.y() >= std::min(p1.y(), p2.y())) && 
                               (point.y() <= std::max(p1.y(), p2.y()));
        if (between_x && between_y) {
            return CGAL::ON_BOUNDARY;
        }
    }
}

// Ray casting algorithm
int crossings = 0;
const Point_2 extreme(std::numeric_limits<typename CGAL::Kernel::FT>::max(), point.y());

for (std::size_t i = 0; i < n; ++i) {
    const Point_2& p1 = polygon[i];
    const Point_2& p2 = polygon[(i + 1) % n];

    // Check if the edge intersects with the ray
    const CGAL::Sign o1 = CGAL::orientation(p1, p2, point);
    const CGAL::Sign o2 = CGAL::orientation(p1, p2, extreme);

    if (o1 != o2) {
        const CGAL::Sign o3 = CGAL::orientation(point, extreme, p1);
        const CGAL::Sign o4 = CGAL::orientation(point, extreme, p2);

        if (o3 != o4) {
            // Check for special case when ray passes through vertex
            if (o1 == CGAL::ZERO && o2 != CGAL::ZERO) {
                const Point_2& prev = polygon[(i - 1 + n) % n];
                const CGAL::Sign prev_orient = CGAL::orientation(prev, p1, point);
                if (prev_orient != CGAL::ZERO) {
                    crossings++;
                }
            } else if (o2 == CGAL::ZERO && o1 != CGAL::ZERO) {
                const Point_2& next = polygon[(i + 2) % n];
                const CGAL::Sign next_orient = CGAL::orientation(p2, next, point);
                if (next_orient != CGAL::ZERO) {
                    crossings++;
                }
            } else {
                crossings++;
            }
        }
    }
}

return (crossings % 2 == 1) ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;

